import React from 'react';
import {AbsoluteFill, useS, en, idx, T, DUR, interpolate, Easing, clamp, ventana, Camara} from './kit';

// FE 2026-11-21 12:00 — Los dos hombres que no murieron (Elias y Enoc). Todo atado a la voz real: T(), en(), DUR.
export const SUBS = {arriba: 230, acento: '#ffd98a'};

const E = Easing.inOut(Easing.cubic);
const ez = (s: number, t: number, d = 1) => interpolate(s, [t, t + d], [0, 1], {...clamp, easing: E});
const ln = (s: number, a: number, b: number, x: number, y: number) => interpolate(s, [a, b], [x, y], clamp);
const hx = (c: string) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const mx = (a: number[], b: number[], t: number) => a.map((v, i) => v + (b[i] - v) * t);
const rgb = (a: number[]) => 'rgb(' + a.map((v) => Math.round(v)).join(',') + ')';

// Escenas: 0 = gancho (colinas), 1 = Jordan, 2 = valle de Enoc, 3 = "La Biblia lo dice" (mismo valle), 4 = cierre (colinas)
const B = [0, en('Iba'), en('No'), T(idx('Biblia', 2) - 1), en('Uno')];
const K = {
  carro: en('carro'), cab: en('caballos'), sep: en('separó'), sub: en('subió'), tor: en('torbellino', 1),
  mares: en('mares'), bajar: en('bajar'), unas: en('unas'), pocas: en('pocas'), lineas: en('líneas'), cinco: en('cinco'),
  llam: en('llamaba'), dios: en('Dios'), dos: en('dos', 2), cam: en('Caminó'), tres: en('Trescientos'), cam2: en('caminó', 2),
  desp: en('después'), nac: en('nació'), dia: en('día', 1), des: en('desapareció'), llev: en('llevó'),
  uno: en('Uno'), tor2: en('torbellino', 2), otro: en('otro'), sin: en('Sin'), ruido: en('ruido'), mil2: en('milagros', 2),
  gran: en('grande'), conm: en('conmueve'), dia2: en('día', 2), impr: en('impresiona'),
  prim: en('primero'), fuego1: en('fuego', 1), elias: en('Elías', 1), adiv: en('adivinas'),
};

/* ---------- definiciones de color ---------- */
const Defs: React.FC = () => (
  <defs>
    <linearGradient id="skinA" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#d9a679" /><stop offset=".55" stopColor="#bf8660" /><stop offset="1" stopColor="#9d6a49" /></linearGradient>
    <linearGradient id="skinB" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#f0c7a0" /><stop offset=".55" stopColor="#dca37b" /><stop offset="1" stopColor="#c0845f" /></linearGradient>
    <radialGradient id="flameO"><stop offset="0" stopColor="#ffd36e" /><stop offset=".6" stopColor="#ff8a2e" /><stop offset="1" stopColor="#d8421a" /></radialGradient>
    <radialGradient id="flameY"><stop offset="0" stopColor="#fff3b0" /><stop offset="1" stopColor="#ffc247" /></radialGradient>
    <linearGradient id="gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff1b0" /><stop offset=".5" stopColor="#f0b24d" /><stop offset="1" stopColor="#b9692a" /></linearGradient>
    <radialGradient id="gFuego"><stop offset="0" stopColor="#ffb347" stopOpacity=".85" /><stop offset=".45" stopColor="#ff6a1a" stopOpacity=".32" /><stop offset="1" stopColor="#ff6a1a" stopOpacity="0" /></radialGradient>
    <radialGradient id="gSoft"><stop offset="0" stopColor="#f2f9ff" stopOpacity=".95" /><stop offset=".4" stopColor="#a9d4ff" stopOpacity=".34" /><stop offset="1" stopColor="#a9d4ff" stopOpacity="0" /></radialGradient>
    <radialGradient id="gCalido"><stop offset="0" stopColor="#fff1c4" stopOpacity=".9" /><stop offset=".5" stopColor="#ffd98a" stopOpacity=".28" /><stop offset="1" stopColor="#ffd98a" stopOpacity="0" /></radialGradient>
    <linearGradient id="cNoche" gradientUnits="userSpaceOnUse" x1="0" y1="-2000" x2="0" y2="1500"><stop offset="0" stopColor="#04061a" /><stop offset=".5" stopColor="#0e1238" /><stop offset=".8" stopColor="#1d2152" /><stop offset="1" stopColor="#4a3a68" /></linearGradient>
    <linearGradient id="cHill" gradientUnits="userSpaceOnUse" x1="0" y1="1080" x2="0" y2="1800"><stop offset="0" stopColor="#1f1d44" /><stop offset="1" stopColor="#090818" /></linearGradient>
    <linearGradient id="cAtard" gradientUnits="userSpaceOnUse" x1="0" y1="-2800" x2="0" y2="1300"><stop offset="0" stopColor="#0f0d33" /><stop offset=".55" stopColor="#4a2f6e" /><stop offset=".75" stopColor="#a04a7a" /><stop offset=".9" stopColor="#e8786f" /><stop offset="1" stopColor="#ffc27a" /></linearGradient>
    <linearGradient id="cRio" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f7b28b" /><stop offset=".5" stopColor="#a58ab0" /><stop offset="1" stopColor="#4f5b9b" /></linearGradient>
    <linearGradient id="cOrilla" gradientUnits="userSpaceOnUse" x1="0" y1="1500" x2="0" y2="2300"><stop offset="0" stopColor="#9c7656" /><stop offset=".4" stopColor="#6a4b3b" /><stop offset="1" stopColor="#2f2229" /></linearGradient>
    <linearGradient id="cManto" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#8a6446" /><stop offset="1" stopColor="#4d3424" /></linearGradient>
    <linearGradient id="luzV" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff6d0" stopOpacity="0" /><stop offset=".35" stopColor="#fff0b8" stopOpacity=".85" /><stop offset=".8" stopColor="#ffe08a" stopOpacity=".7" /><stop offset="1" stopColor="#ffe08a" stopOpacity="0" /></linearGradient>
    <linearGradient id="luzH" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#fff6d0" stopOpacity="0" /><stop offset=".5" stopColor="#fff6d0" stopOpacity="1" /><stop offset="1" stopColor="#fff6d0" stopOpacity="0" /></linearGradient>
    <linearGradient id="haz" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff6d6" stopOpacity=".75" /><stop offset="1" stopColor="#fff6d6" stopOpacity="0" /></linearGradient>
    <linearGradient id="mar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#b8e3ee" /><stop offset="1" stopColor="#78b6cf" /></linearGradient>
    <linearGradient id="robeSh" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#fff" stopOpacity=".2" /><stop offset=".5" stopColor="#fff" stopOpacity="0" /><stop offset="1" stopColor="#000" stopOpacity=".25" /></linearGradient>
  </defs>
);

/* ---------- personas ---------- */
type PP = {
  x: number; y: number; k?: number; s: number; ph?: number; walk?: number; face?: number;
  robe: string; robe2: string; skin?: string; hair?: string; beard?: string; bald?: boolean; staff?: boolean;
  cloak?: string; fur?: boolean; armR?: number; armL?: number; tilt?: number; op?: number; rot?: number; talk?: number;
};
const Persona: React.FC<PP> = ({x, y, k = 1, s, ph = 0, walk = 1, face = 1, robe, robe2, skin = 'url(#skinA)', hair = '#cfc8bb', beard, bald, staff, cloak, fur, armR = 0, armL = 0, tilt = 0, op = 1, rot = 0, talk = 0}) => {
  const p = s * 3.1 + ph;
  const bob = Math.abs(Math.sin(p)) * 7 * walk;
  const sway = Math.sin(s * 0.9 + ph) * 2;
  const blink = (s + ph * 1.7) % 3.9 < 0.12 ? 0.12 : 1;
  const leg = (i: number) => {
    const q = p + (i > 0 ? 0 : Math.PI);
    const fx = i * 24 + Math.sin(q) * 42 * walk;
    const fy = -14 - Math.max(0, Math.cos(q)) * 18 * walk;
    return (
      <g key={i}>
        <path d={`M${i * 20} -210L${fx} ${fy}`} stroke="#4b382b" strokeWidth="34" strokeLinecap="round" />
        <ellipse cx={fx + 10} cy={fy + 2} rx="34" ry="13" fill="#2d2119" />
      </g>
    );
  };
  const arm = (side: number, extra: number) => {
    const sx = side * 70;
    const sy = -410 - bob;
    const a = Math.sin(p + (side > 0 ? Math.PI : 0)) * 0.42 * walk + 0.16 + extra;
    const hxx = sx + side * Math.sin(a) * 190;
    const hyy = sy + Math.cos(a) * 190;
    return (
      <g key={side}>
        <path d={`M${sx} ${sy}L${hxx} ${hyy}`} stroke={robe} strokeWidth="42" strokeLinecap="round" />
        <path d={`M${sx} ${sy}L${hxx} ${hyy}`} stroke="url(#robeSh)" strokeWidth="42" strokeLinecap="round" />
        <circle cx={hxx} cy={hyy + 8} r="21" fill={skin} />
        {staff && side > 0 && <path d={`M${hxx} ${hyy - 250}L${hxx + 6} 4`} stroke="#6b4a32" strokeWidth="13" strokeLinecap="round" />}
      </g>
    );
  };
  const fx7 = face * 7;
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`} opacity={op}>
      <ellipse cy="2" rx="112" ry="18" fill="#000" opacity=".28" />
      {leg(-1)}{leg(1)}
      <g transform={`translate(${sway} ${-bob})`}>
        <path d={`M-66 -428Q0 -462 66 -428L104 -80Q0 ${-48 + Math.sin(p * 2) * 5} -104 -80Z`} fill={robe} />
        <path d={`M-66 -428Q0 -462 66 -428L104 -80Q0 ${-48 + Math.sin(p * 2) * 5} -104 -80Z`} fill="url(#robeSh)" />
        <path d="M-40 -380Q-48 -250 -58 -110M16 -400Q20 -250 14 -90M52 -370Q66 -250 80 -110" stroke="#000" strokeOpacity=".12" strokeWidth="8" fill="none" />
        <path d="M-90 -266Q0 -242 90 -266L86 -232Q0 -208 -88 -232Z" fill={robe2} />
        {cloak && (
          <g>
            {[1, -1].map((m) => (
              <g key={m} transform={`scale(${m} 1)`}>
                <path d={`M-100 -430Q-70 -452 -40 -442L-30 -150${fur ? 'L-52 -112L-72 -148L-96 -108L-128 -134' : 'Q-60 -100 -118 -118'}Z`} fill={cloak} />
                <path d="M-84 -420Q-96 -300 -108 -170" stroke="#fff" strokeOpacity=".16" strokeWidth="8" fill="none" />
                {fur && <path d="M-70 -400L-84 -330M-60 -360L-76 -290M-54 -300L-70 -230" stroke="#2c1c12" strokeOpacity=".3" strokeWidth="5" />}
              </g>
            ))}
          </g>
        )}
        <rect x="-18" y="-468" width="36" height="52" rx="14" fill={skin} />
        {arm(-1, armL)}
        {arm(1, armR)}
        <g transform={`translate(0 -524) rotate(${tilt * 57.3})`}>
          <circle cx="-54" cy="6" r="12" fill={skin} /><circle cx="54" cy="6" r="12" fill={skin} />
          <ellipse rx="54" ry="64" fill={skin} />
          {bald ? (
            <g>
              <ellipse cx="-52" cy="-2" rx="9" ry="20" fill="#3b2a22" /><ellipse cx="52" cy="-2" rx="9" ry="20" fill="#3b2a22" />
              <ellipse cx="-16" cy="-46" rx="24" ry="9" fill="#fff" opacity=".32" />
            </g>
          ) : (
            <g>
              <path d="M-57 -8Q-66 -84 0 -74Q68 -84 57 -8Q50 -42 20 -48Q-20 -36 -57 -8Z" fill={hair} />
              <path d="M-57 -8Q-72 30 -52 62M57 -8Q72 30 52 62" stroke={hair} strokeWidth="14" strokeLinecap="round" fill="none" />
            </g>
          )}
          {beard && <path d="M-50 12Q-58 90 0 108Q58 90 50 12Q24 46 0 40Q-24 46 -50 12Z" fill={beard} />}
          <circle cx="-30" cy="22" r="14" fill="#e08a6a" opacity=".14" /><circle cx="30" cy="22" r="14" fill="#e08a6a" opacity=".14" />
          {[-1, 1].map((i) => (
            <g key={i}>
              <ellipse cx={i * 21 + fx7} cy="-4" rx="7.5" ry={10 * blink} fill="#1b130f" />
              <circle cx={i * 21 + fx7 + 2} cy="-8" r="2.6" fill="#fff" />
              <path d={`M${i * 21 + fx7 - 12} -22Q${i * 21 + fx7} -30 ${i * 21 + fx7 + 12} -21`} stroke={bald ? '#7a5238' : hair === '#cfc8bb' ? '#8d867a' : '#6f6a61'} strokeWidth="5" strokeLinecap="round" fill="none" />
            </g>
          ))}
          <path d={`M${3 + fx7} 4Q${10 + fx7} 16 ${fx7} 22`} stroke="#8a5b43" strokeOpacity=".55" strokeWidth="4" strokeLinecap="round" fill="none" />
          <path d={`M${-14 + fx7} 38Q${fx7} ${46 + talk * Math.abs(Math.sin(s * 9 + ph)) * 8} ${14 + fx7} 37`} stroke="#7a3f33" strokeWidth="4.5" strokeLinecap="round" fill="none" />
        </g>
      </g>
    </g>
  );
};

const Silueta: React.FC<{x: number; y: number; k?: number; rim?: string; o?: number; rimO?: number; s?: number; walk?: number}> = ({x, y, k = 1, rim = '#fff', o = 1, rimO = 0.6, s = 0, walk = 0}) => (
  <g transform={`translate(${x} ${y}) scale(${k}) rotate(${Math.sin(s * 0.8) * 1.2})`} opacity={o}>
    {walk > 0 && [-1, 1].map((i) => <path key={i} d={`M${i * 14} -20L${i * 20 + Math.sin(s * 6 + (i > 0 ? 0 : Math.PI)) * 28 * walk} 0`} stroke="#07070f" strokeWidth="22" strokeLinecap="round" />)}
    <path d="M-46 -10Q-58 -170 -24 -230Q0 -250 24 -230Q58 -170 46 -10Z" fill="#07070f" stroke={rim} strokeOpacity={rimO} strokeWidth="5" />
    <circle cy="-285" r="38" fill="#07070f" stroke={rim} strokeOpacity={rimO} strokeWidth="5" />
  </g>
);

/* ---------- fuego ---------- */
const Llama: React.FC<{x: number; y: number; w: number; h: number; s: number; i?: number; o?: number}> = ({x, y, w, h, s, i = 0, o = 1}) => {
  const a = Math.sin(s * 7 + i * 1.7) * w * 0.25;
  const b = Math.sin(s * 9 + i * 2.3) * w * 0.2;
  return (
    <g transform={`translate(${x} ${y})`} opacity={o}>
      <path d={`M${-w} 0Q${-w * 1.1} ${-h * 0.4} ${a} ${-h}Q${w * 0.3 + b} ${-h * 0.45} ${w} 0Z`} fill="url(#flameO)" />
      <path d={`M${-w * 0.6} 0Q${-w * 0.65} ${-h * 0.35} ${a * 0.7} ${-h * 0.7}Q${w * 0.2} ${-h * 0.3} ${w * 0.6} 0Z`} fill="url(#flameY)" />
      <path d={`M${-w * 0.28} 0Q${-w * 0.3} ${-h * 0.2} ${a * 0.4} ${-h * 0.42}Q${w * 0.1} ${-h * 0.2} ${w * 0.28} 0Z`} fill="#fff6cf" />
    </g>
  );
};

const Caballo: React.FC<{x: number; y: number; k: number; s: number; i: number}> = ({x, y, k, s, i}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    {[-90, -45, 60, 100].map((lx, j) => (
      <path key={j} d={`M${lx} -90L${lx + Math.sin(s * 8 + j * 1.6 + i) * 34} ${-6 - Math.max(0, Math.cos(s * 8 + j * 1.6 + i)) * 24}`} stroke="url(#flameO)" strokeWidth="22" strokeLinecap="round" />
    ))}
    <ellipse cy="-125" rx="135" ry="56" fill="url(#flameO)" />
    <path d="M70 -150Q125 -235 150 -275L208 -262Q222 -232 178 -190L132 -108Z" fill="url(#flameO)" />
    <path d="M150 -275L208 -262L222 -236L168 -246Z" fill="url(#flameY)" />
    <circle cx="188" cy="-252" r="6" fill="#4a1408" /><circle cx="190" cy="-254" r="2" fill="#fff" />
    <Llama x={-130} y={-140} w={26} h={150} s={s} i={i} />
    <Llama x={110} y={-212} w={18} h={90} s={s} i={i + 2} />
    <Llama x={84} y={-180} w={16} h={80} s={s} i={i + 4} />
  </g>
);

const Carro: React.FC<{x: number; y: number; k: number; s: number; rot: number; o: number}> = ({x, y, k, s, rot, o}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`} opacity={o}>
    <circle cx="-200" cy="-80" r="460" fill="url(#gFuego)" />
    <Caballo x={-330} y={0} k={1} s={s} i={0} />
    <Caballo x={-570} y={14} k={0.94} s={s} i={3} />
    <path d="M-110 0H110L146 -122H-124Z" fill="url(#gold)" />
    <path d="M-124 -122H146" stroke="#fff3b8" strokeWidth="10" strokeLinecap="round" />
    <path d="M-110 -30Q0 -14 110 -30" stroke="#8a4a1d" strokeOpacity=".4" strokeWidth="6" fill="none" />
    {[-40, 70].map((wx, j) => (
      <g key={j} transform={`translate(${wx} 12) rotate(${s * 140 * (j ? 1 : -1)})`}>
        <circle r="56" fill="none" stroke="#ffb347" strokeWidth="14" />
        <path d="M-56 0H56M0 -56V56M-40 -40L40 40M40 -40L-40 40" stroke="#ffd36e" strokeWidth="6" />
      </g>
    ))}
    <Llama x={-120} y={-118} w={26} h={110} s={s} i={5} />
    <Llama x={130} y={-120} w={24} h={100} s={s} i={7} />
  </g>
);

const Remolino: React.FC<{x: number; y: number; h: number; w: number; s: number; o?: number}> = ({x, y, h, w, s, o = 1}) => (
  <g opacity={o}>
    {Array.from({length: 9}, (_, i) => {
      const f = i / 8;
      const cy = y - f * h;
      return <ellipse key={i} cx={x + Math.sin(s * 3.2 + i * 0.9) * (14 + f * 40)} cy={cy} rx={w * (0.35 + f * 0.75)} ry={14 + f * 10} fill="none" stroke={i % 2 ? '#ffd27a' : '#ff9a45'} strokeWidth="9" strokeOpacity={0.22 + (1 - f) * 0.22} transform={`rotate(${Math.sin(s * 2 + i) * 8} ${x} ${cy})`} />;
    })}
  </g>
);

const Manto: React.FC<{x: number; y: number; rot: number; k?: number}> = ({x, y, rot, k = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    <path d="M-110 -90Q0 -150 110 -90L130 80L100 56L80 104L50 52L20 104L-10 52L-40 104L-70 52L-100 104L-130 80Z" fill="url(#cManto)" />
    <path d="M-80 -80L-96 20M-30 -100L-38 30M30 -100L36 30M80 -80L92 20" stroke="#2c1c12" strokeOpacity=".35" strokeWidth="6" />
    <path d="M-100 -80Q0 -130 100 -80" stroke="#d4a574" strokeOpacity=".5" strokeWidth="6" fill="none" />
  </g>
);

/* ---------- colinas de noche (escenas 1 y 5) ---------- */
const Noche: React.FC<{s: number; fire: number; soft: number; silF?: boolean; silS?: boolean; walk?: number; whirl?: number; stars?: number}> = ({s, fire, soft, silF, silS, walk = -1, whirl = -1, stars = 0}) => {
  const fl = 0.9 + 0.1 * Math.sin(s * 9) * Math.sin(s * 4.1);
  const wx = interpolate(walk, [0, 0.3, 0.55, 0.8, 1], [650, 780, 845, 888, 955], clamp);
  const wy = interpolate(walk, [0, 0.3, 0.55, 0.8, 1], [1424, 1404, 1248, 1104, 1094], clamp);
  const moving = walk >= 0 && walk < 1 ? 1 : 0;
  return (
    <g>
      <rect x="-1000" y="-2000" width="3200" height="4400" fill="url(#cNoche)" />
      {Array.from({length: 110}, (_, i) => (
        <circle key={i} cx={-700 + ((i * 173) % 1900)} cy={((i * 311) % 2400) - 1300} r={1.2 + (i % 4) * 0.7} fill="#fff" opacity={Math.max(0.08, (0.35 + 0.45 * Math.sin(s * 1.2 + i * 1.3)) * (0.6 + stars * 0.4))} />
      ))}
      <circle cx="900" cy="1060" r="640" fill="url(#gSoft)" opacity={soft * (0.85 + 0.15 * Math.sin(s * 1.1))} />
      <path d={`M${900 + Math.sin(s * 0.3) * 30} 1080L560 -400L1240 -400Z`} fill="url(#haz)" opacity={0.28 * soft} />
      <path d={`M${900} 1080L${760 + Math.sin(s * 0.4 + 1) * 60} -400L${900 + Math.sin(s * 0.4 + 1) * 60} -400Z`} fill="url(#haz)" opacity={0.2 * soft} />
      <circle cx="220" cy="1090" r="560" fill="url(#gFuego)" opacity={fire * fl} />
      <path d="M-1000 1360Q-400 1270 100 1330Q500 1260 1000 1340Q1500 1280 2200 1350V1900H-1000Z" fill="#241f4a" />
      <path d="M-1000 1900L-1000 1430Q-520 1390 -60 1290Q130 1165 222 1162Q330 1168 430 1300Q520 1420 640 1422Q780 1402 840 1245Q885 1098 962 1088Q1052 1094 1128 1235Q1260 1385 2200 1400L2200 1900Z" fill="url(#cHill)" />
      <path d="M60 1240Q130 1165 222 1162Q330 1168 400 1260" stroke="#ff9a45" strokeOpacity={0.6 * fire} strokeWidth="6" fill="none" />
      <path d="M840 1245Q885 1098 962 1088Q1052 1094 1100 1190" stroke="#bfe0ff" strokeOpacity={0.65 * soft} strokeWidth="6" fill="none" />
      {fire > 0.02 && (
        <g opacity={Math.min(1, fire * 1.2)}>
          {[-62, 0, 62].map((o, i) => <Llama key={i} x={222 + o} y={1166} w={36 + (i === 1 ? 14 : 0)} h={(i === 1 ? 175 : 125) * (0.5 + fire * 0.5)} s={s} i={i} />)}
          {Array.from({length: 18}, (_, i) => {
            const f = ((s * 0.35 + i * 0.137) % 1);
            return <circle key={i} cx={222 + Math.sin(s * 1.1 + i * 1.7) * 70 + (i - 9) * 6} cy={1160 - f * 560} r="3.4" fill="#ffc36b" opacity={(1 - f) * 0.9 * fire} />;
          })}
        </g>
      )}
      {whirl >= 0 && (
        <g>
          <Remolino x={222} y={1180} h={1700 * ez(s, whirl, 2.2)} w={120} s={s} o={ln(s, whirl, whirl + 0.6, 0, 1) * ln(s, whirl + 3.4, whirl + 5.4, 1, 0)} />
          <Llama x={222 + Math.sin(s * 3) * 30} y={1180 - 1700 * ez(s, whirl, 2.2)} w={70} h={230} s={s} i={9} o={ln(s, whirl, whirl + 0.6, 0, 1) * ln(s, whirl + 2.2, whirl + 3.6, 1, 0)} />
        </g>
      )}
      {silF && <Silueta x={224} y={1172} k={0.4} rim="#ffb36b" rimO={0.55 + 0.3 * fire} s={s} />}
      {silS && <Silueta x={960} y={1096} k={0.4} rim="#cfe8ff" s={s} />}
      {walk >= 0 && (
        <g>
