  const ey = 1640 - 1450 * up;
  const rot = ez(s, K.tor, 2.8) * 720;
  const xs = 690 + 90 * sepE;
  const tm = K.tor + 1.0;
  const pm = ln(s, tm, B[2] - 0.1, 0, 1);
  const em = pm * pm * (3 - 2 * pm);
  const mantoX0 = 330, mantoY0 = 1640 - 1450 * ez(tm, K.sub, 3.6) - 320;
  const mx0 = mantoX0 + Math.sin(Math.max(0, tm - K.sub) * 2.3) * 90 * ez(tm, K.sub, 3.6);
