  const aw = ez(s, K.carro + 0.4, 0.8);
  const catchA = ez(s, tm + 0.6, 1.4);
  const arms = 1.0 * aw + 1.2 * catchA;
  const carroY = ln(s, K.carro - 0.4, K.cab + 0.6, -300, 930) - 1700 * ez(s, K.sub + 0.2, 3.4);
  const carroX = 560 + Math.sin(s * 2) * 24 + (ex - 560) * up * 0.5;
  const carroO = ln(s, K.carro - 0.4, K.carro + 0.3, 0, 1);
  const vortO = ln(s, K.carro, K.cab, 0, 1) * (1 - up * 0.2);
  const vx = s < K.sub ? 540 : ex;
  return (
    <g>
