      <rect x="-1000" y="1300" width="3200" height="250" fill="url(#cRio)" />
      {Array.from({length: 9}, (_, i) => <ellipse key={i} cx={770 + Math.sin(s * 1.4 + i) * 22} cy={1316 + i * 24} rx={110 - i * 7} ry="5" fill="#fff0b8" opacity={0.5 - i * 0.04} />)}
      {Array.from({length: 22}, (_, i) => {
        const x = ((i * 211 - D * 0.5 + s * 12) % 1800 + 1800) % 1800 - 300;
        return <path key={i} d={`M${x} ${1340 + (i % 7) * 30}q30 -7 60 0`} stroke="#fff" strokeOpacity=".3" strokeWidth="4" fill="none" />;
      })}
      <path d="M-1000 1550Q-300 1500 300 1548Q900 1500 2200 1540V2400H-1000Z" fill="url(#cOrilla)" />
      <path d="M-1000 1640H2200V1730H-1000Z" fill="#b58e68" opacity=".4" />
      {Array.from({length: 18}, (_, i) => {
        const x = (((i * 173 - D) % 1800) + 1800) % 1800 - 360;
