        return (
          <g key={i} transform={`translate(${x} ${y})`}>
            <path d={`M0 60Q${sw} 0 ${sw * 2} -60M12 60Q${12 + sw} 10 ${14 + sw * 2} -40M-12 60Q${-12 + sw} 10 ${-10 + sw * 2} -44`} stroke="#6f7f45" strokeWidth="6" fill="none" strokeLinecap="round" />
          </g>
