      <circle cx="540" cy="1000" r="520" fill="url(#gFuego)" opacity={ez(s, K.carro, 1.2) * (1 - up * 0.5)} />
      {vortO > 0 && <Remolino x={vx} y={s < K.sub ? 1650 : ey + 320} h={s < K.sub ? 640 : Math.max(200, 1000 - up * 300)} w={150} s={s} o={vortO} />}
